import{_ as o,o as r,c as s,ag as d}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"SKY-001「工程世界模型」转述核实","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/sky-001-engineering-world-model.md","filePath":"topics/ai-system-architecture/sky-001-engineering-world-model.md"}'),n={name:"topics/ai-system-architecture/sky-001-engineering-world-model.md"};function e(a,t,g,i,l,u){return r(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="sky-001「工程世界模型」转述核实" tabindex="-1">SKY-001「工程世界模型」转述核实 <a class="header-anchor" href="#sky-001「工程世界模型」转述核实" aria-label="Permalink to &quot;SKY-001「工程世界模型」转述核实&quot;">​</a></h1><blockquote><p>关键词：SKY-001, Skyfall AI, 工程世界模型, Engineering World Model, 世界模型, World Model, 企业世界模型, Enterprise World Model, CAD, BIM, GPT-6 Astra, Sam Pasupalak, Maluuba, 微软收购, 150倍成本, 50倍速度, IoU, waitlist, 首个, 程度夸大, 口径错位, 转述核实, 通用工程师</p></blockquote><p><strong>核实日期</strong>：2026-10-24 ｜ <strong>一手源</strong>：<code>https://skyfall.ai/blog/introducing-sky-001</code>（2026-10-19，署名 Skyfall Research）</p><hr><h2 id="一句话结论" tabindex="-1">一句话结论 <a class="header-anchor" href="#一句话结论" aria-label="Permalink to &quot;一句话结论&quot;">​</a></h2><p><strong>是真的发布了，但&quot;全面碾压&quot;是把&quot;速度、成本两个维度的量级优势&quot;包装成了全面优势——官方自己写的是&quot;持平&quot;：IoU 79.7% vs 79.1%，只高 0.6 个百分点。</strong> 转述的核心数字（3.9s/199s、150×成本）<strong>都能在官方页面找到原样出处</strong>，但三处措辞失真、六件关键事实被省掉。</p><hr><h2 id="一、事实底盘-官方一手" tabindex="-1">一、事实底盘（官方一手） <a class="header-anchor" href="#一、事实底盘-官方一手" aria-label="Permalink to &quot;一、事实底盘（官方一手）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>官方内容</th></tr></thead><tbody><tr><td>发布</td><td>2026-10-19，官方博客《Introducing SKY-001: The First World Model for Engineering》</td></tr><tr><td>定位（官方自称）</td><td>&quot;<strong>The First World Model for Engineering</strong>&quot;；FAQ 原话：像一位 &quot;<strong>General Engineer</strong>&quot; 一样把实物可视化</td></tr><tr><td>架构</td><td>两阶段：<strong>Hierarchical Composer</strong>（生成目标 → 逐层展开为元素层级）+ <strong>Construction World Model</strong>（预测建造每个叶节点的<strong>视觉状态序列</strong>）</td></tr><tr><td>任务</td><td><strong>CAD</strong>：产品照片 → 总成/零件层级 + 每个零件的草图与操作序列；<strong>BIM</strong>：楼栋轮廓 → 单元布局 → 各单元房间</td></tr><tr><td>官方结论句</td><td>&quot;SKY-001 achieves <strong>about a 50× speedup</strong> and <strong>costs about 150 times less</strong> per case, <strong>while matching its performance</strong>（79.7% IoU against 79.1%）&quot;</td></tr></tbody></table><h3 id="cad-构建基准-1-000-个组件-捷豹-e-type、fanuc-arcmate-100ib-机械臂、minitractor-4×4、bell-222-直升机、喷气发动机-每例约-100-个绘制步骤-指标-iou" tabindex="-1">CAD 构建基准（1,000 个组件：捷豹 E-Type、FANUC ArcMate 100iB 机械臂、Minitractor 4×4、Bell 222 直升机、喷气发动机；每例约 100 个绘制步骤；指标 IoU） <a class="header-anchor" href="#cad-构建基准-1-000-个组件-捷豹-e-type、fanuc-arcmate-100ib-机械臂、minitractor-4×4、bell-222-直升机、喷气发动机-每例约-100-个绘制步骤-指标-iou" aria-label="Permalink to &quot;CAD 构建基准（1,000 个组件：捷豹 E-Type、FANUC ArcMate 100iB 机械臂、Minitractor 4×4、Bell 222 直升机、喷气发动机；每例约 100 个绘制步骤；指标 IoU）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>时间/例</th><th>成本/例</th><th>IoU</th></tr></thead><tbody><tr><td><strong>SKY-001</strong></td><td><strong>3.9 s</strong></td><td><strong>$0.005</strong></td><td><strong>79.7%</strong></td></tr><tr><td>GPT-6 Astra</td><td>199 s</td><td>$0.75</td><td>79.1%</td></tr><tr><td>Gemini 4</td><td>253 s</td><td>$0.25</td><td>76.9%</td></tr><tr><td>Qwen 3.8 Max</td><td>764 s</td><td>$0.30</td><td>34.4%</td></tr><tr><td>Kimi K3</td><td>439 s</td><td>$0.13</td><td>9.5%</td></tr><tr><td>Grok 4.7</td><td>1250 s</td><td>$0.59</td><td>无输出</td></tr></tbody></table><h3 id="bim-构建基准-1-000-份平面图-约-350-个整层来自-ifc-建筑模型-650-个户型级-每例-20-200-步-均值约-70-步" tabindex="-1">BIM 构建基准（1,000 份平面图：约 350 个整层来自 IFC 建筑模型 + 650 个户型级；每例 20~200+ 步，均值约 70 步） <a class="header-anchor" href="#bim-构建基准-1-000-份平面图-约-350-个整层来自-ifc-建筑模型-650-个户型级-每例-20-200-步-均值约-70-步" aria-label="Permalink to &quot;BIM 构建基准（1,000 份平面图：约 350 个整层来自 IFC 建筑模型 + 650 个户型级；每例 20~200+ 步，均值约 70 步）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>时间/例</th><th>成本/例</th><th>IoU</th></tr></thead><tbody><tr><td><strong>SKY-001</strong></td><td><strong>1.22 s</strong></td><td><strong>$0.0024</strong></td><td><strong>43.6%</strong></td></tr><tr><td>GPT-6 Astra</td><td>144.6 s</td><td>$0.446</td><td>40.6%</td></tr><tr><td>Gemini 3.8 Flash</td><td>346.2 s</td><td>$0.218</td><td><strong>42.3%</strong></td></tr><tr><td>Kimi K3</td><td><strong>113.9 s</strong></td><td>$0.270</td><td>33.7%</td></tr><tr><td>Qwen 3.8 Max</td><td>255.3 s</td><td>$0.111</td><td>28.8%</td></tr><tr><td>Grok 4.7</td><td>592.1 s</td><td>$0.305</td><td>28.2%</td></tr></tbody></table><blockquote><p>★ 注意 BIM 表：<strong>Kimi K3 比 Astra 更快，Gemini 3.8 Flash 的 IoU 比 Astra 更高</strong> → Astra 并非&quot;最强基线&quot;，&quot;碾压&quot;只在时间/成本维度对 Astra 成立。</p></blockquote><p><strong>训练数据</strong>：SKY-001 自建资产含 <strong>542–988 个精细网格构件</strong>（含小型五金件与内部零件），对照公开数据集 <strong>PartVerse 仅 8–85 个粗语义件</strong>。</p><p><strong>盲测（层级化组件器）</strong>：两个 LLM 评委，1–10 分均值 —— SKY-001 7.8 / 7.3 / 8.0 / 8.1 / 7.7，GPT-6 Astra 6.4 / 6.3 / 7.3 / 6.7 / 7.4；<strong>Astra 只为 82% 的资产返回了模型</strong>。</p><hr><h2 id="二、逐条核对-转述-→-官方-→-判定" tabindex="-1">二、逐条核对（转述 → 官方 → 判定） <a class="header-anchor" href="#二、逐条核对-转述-→-官方-→-判定" aria-label="Permalink to &quot;二、逐条核对（转述 → 官方 → 判定）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>转述原话</th><th>官方实际</th><th>判定</th></tr></thead><tbody><tr><td>1</td><td>&quot;发布了<strong>全球首个</strong>工程世界模型&quot;</td><td>官方自称 &quot;The First World Model for Engineering&quot;</td><td>🟡 发布属实；&quot;首个&quot;是<strong>自我宣称</strong>，无第三方认定（官网同时自称首个 &quot;Enterprise World Model&quot;）</td></tr><tr><td>2</td><td>&quot;号称 AI <strong>通用工程师</strong>&quot;</td><td>FAQ 原话 &quot;just like a &#39;General Engineer&#39;&quot;</td><td>✅ 属实</td></tr><tr><td>3</td><td>&quot;CAD 设计上<strong>全面碾压</strong> GPT-6 Astra&quot;</td><td>&quot;<strong>matches or exceeds</strong>&quot;；结论句明写 &quot;<strong>while matching its performance</strong>&quot;</td><td>⚠️ <strong>程度夸大</strong>：量级优势在速度/成本，精度是<strong>持平</strong></td></tr><tr><td>4</td><td>&quot;<strong>成本降低 150 倍</strong>&quot;</td><td>官方英文 &quot;costs about <strong>150 times less</strong>&quot;（$0.75 → $0.005）</td><td>⚠️ <strong>口径错</strong>：正确含义是<strong>成本降到 1/150</strong>（便宜 150 倍）；&quot;降低 150 倍&quot;数学上不成立——<strong>官方英文本身就是病句，中文是直译</strong></td></tr><tr><td>5</td><td>&quot;速度提升 <strong>50 倍</strong>&quot;</td><td>官方博客 &quot;about a <strong>50×</strong> speedup&quot;；卡片写 51×；FAQ 写 &quot;<strong>100 times</strong> the speed&quot;</td><td>✅ 与博客口径一致（199/3.9 = 51.0×）；⚠️ 官方<strong>自身三处口径打架</strong></td></tr><tr><td>6</td><td>&quot;设计 1 个 vs 150 个&quot;</td><td>1/150 成本</td><td>✅ 推导一致（同成本约可做 150 个）</td></tr><tr><td>7</td><td>&quot;199 秒 vs 3.9 秒&quot;</td><td>199 s / 3.9 s</td><td>✅ 与官方<strong>逐字一致</strong></td></tr><tr><td>8</td><td>&quot;精度<strong>还更高</strong>&quot;</td><td>79.7% vs 79.1% IoU</td><td>⚠️ <strong>方向对、量级被吞</strong>：只高 <strong>0.6 个百分点</strong>（BIM 是 43.6% vs 40.6%，但 Gemini 3.8 Flash 42.3% 高于 Astra）</td></tr><tr><td>9</td><td>&quot;专为复杂工程设计&quot;</td><td>✅ 官方叙事核心</td><td>✅ 属实</td></tr><tr><td>10</td><td>&quot;在<strong>视觉世界里规划</strong>，再拆解为零件&quot;</td><td>&quot;planning directly in the visual world&quot; + 层级拆解</td><td>✅ <strong>准确</strong>（近直译）</td></tr><tr><td>11</td><td>&quot;从整体到<strong>螺栓</strong>，构建完整结构&quot;</td><td>&quot;from large structural pieces all the way down to <strong>tiny screws and fasteners</strong>&quot;</td><td>✅ <strong>准确</strong>（近直译）</td></tr><tr><td>12</td><td>&quot;下一步<strong>连接机器人</strong>和真实世界反馈 → <strong>自主制造</strong>核心支柱&quot;</td><td>官方 &quot;What Comes Next&quot; 讲的是：CAD 草图→<strong>可执行操作 + 可编辑特征历史</strong>、文本指令引导设计、BIM 扩展；官网首页真实叙事是 <strong>Enterprise World Model → 业务自主运营</strong>，SKY-001 只自称 &quot;Our first stop is Design &amp; Engineering&quot;</td><td>🟡 <strong>方向偏</strong>：未见&quot;连接机器人/自主制造&quot;的官方对应表述；官方重心是<strong>企业自主运营</strong>而非制造</td></tr></tbody></table><p><strong>统计</strong>：12 条中 ✅ 属实 5 条、⚠️ 失真 3 条（程度夸大 1 / 口径错 1 / 量级被吞 1）、🟡 存疑或方向偏 2 条。</p><hr><h2 id="三、官方口径自身也不一致-值得单独记一笔" tabindex="-1">三、官方口径自身也不一致（值得单独记一笔） <a class="header-anchor" href="#三、官方口径自身也不一致-值得单独记一笔" aria-label="Permalink to &quot;三、官方口径自身也不一致（值得单独记一笔）&quot;">​</a></h2><p>同一套结果，Skyfall 自己写了<strong>三个版本</strong>：</p><table tabindex="0"><thead><tr><th>出处</th><th>速度</th><th>成本</th></tr></thead><tbody><tr><td>博客正文</td><td>about a <strong>50×</strong> speedup</td><td>about <strong>150 times less</strong></td></tr><tr><td>性能卡片</td><td><strong>51×</strong></td><td><strong>150× less than GPT-6 Astra</strong></td></tr><tr><td>官网 FAQ</td><td>&quot;<strong>100 times</strong> the speed&quot;</td><td>&quot;<strong>1/150th</strong> the cost&quot;</td></tr></tbody></table><p>→ 加速比 50× / 51× / 100× 三值互斥（实际算得 51.0×）。<strong>宣传页比博客更激进</strong>，是常见的发布节奏，但读者若只看到 FAQ 会以为速度优势翻倍。</p><hr><h2 id="四、被省略的六件关键事实" tabindex="-1">四、被省略的六件关键事实 <a class="header-anchor" href="#四、被省略的六件关键事实" aria-label="Permalink to &quot;四、被省略的六件关键事实&quot;">​</a></h2><ol><li><strong>只有 waitlist，没有公开访问</strong> —— 官方 FAQ：&quot;Join the waitlist to be the first to hear when it goes public&quot;。<strong>&quot;发布&quot; ≠ &quot;可用&quot;</strong>。</li><li><strong>官方自承输出还不工业级</strong> —— 原文：&quot;<strong>Transitions are illustrative, and the saved sketch and 3D geometry may not match.</strong>&quot; 中文报道据此判断：距可直接投入生产的工业级 CAD 文件&quot;还有相当距离&quot;。</li><li><strong>&quot;首个&quot;是自我宣称，且有邻近先例</strong> —— arXiv <strong>InCoder-32B-Thinking: Industrial Code World Model for Thinking</strong>（2026-04-03，<code>2604.03144</code>）已在做&quot;工业代码世界模型&quot;；而 &quot;World Model for &lt;领域&gt; Design&quot; 已是成熟命名范式（如 ODesign 生物分子交互设计，2025-10-25）。</li><li><strong>海外技术圈几乎零反应</strong> —— HN 三个提交合计 <strong>5 分 / 0 评论</strong>（<code>idid</code> 5 分、<code>doener</code> 2 分、<code>RyanShook</code> 1 分，均 2026-10-19~20）。</li><li><strong>基准是自建自评</strong> —— CAD/BIM benchmark 由 Skyfall 自己构建，IoU 自己计算，盲测评委是<strong>两个 LLM</strong>而非人类工程师。0.6 个百分点的 IoU 差异在这样的设定下不足以支撑&quot;更高&quot;。</li><li><strong>对手不止 Astra</strong> —— 官方其实与 6 个模型同台（含 Gemini 4 / Gemini 3.8 Flash / Qwen 3.8 Max / Kimi K3 / Grok 4.7），转述压成&quot;通用大模型 vs SKY-001&quot;两家对比，抹掉了 Gemini 在 BIM 上的竞争力与 Kimi 的速度。</li></ol><hr><h2 id="五、创始人-公司背景核实" tabindex="-1">五、创始人 / 公司背景核实 <a class="header-anchor" href="#五、创始人-公司背景核实" aria-label="Permalink to &quot;五、创始人 / 公司背景核实&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>核实结果</th><th>来源</th></tr></thead><tbody><tr><td>创始人</td><td><strong>Sam Pasupalak</strong> — 滑铁卢大学数学与计算机；<strong>Maluuba</strong> 四名创始本科生之一（另三位：Zhiyuan Wu、Joshua Pantony、Kaheer Suleman）</td><td>维基 Maluuba 条目 ✅</td></tr><tr><td>Maluuba</td><td><strong>2011 年创立于滑铁卢</strong>；2012-02 Samsung Ventures 种子 $2M；2015-08 A 轮 $9M；2015-12 设蒙特利尔 R&amp;D 实验室；<strong>2017 年被微软收购</strong>（维基未载金额）</td><td>维基 Maluuba 条目 ✅</td></tr><tr><td>&quot;卖身微软 <strong>15 年</strong>后&quot;</td><td>⚠️ <strong>时间口径有偏</strong>：微软收购在 <strong>2017</strong>（距 2026 为 9 年）；按<strong>公司创办 2011</strong> 计才是 15 年</td><td>计算 + 维基</td></tr><tr><td>收购金额 1.6 亿美元</td><td>🟡 中文报道口径，<strong>未获一手确认</strong></td><td>中文报道</td></tr><tr><td>Skyfall AI</td><td>中文报道称 <strong>2025 年 4 月创立于旧金山</strong>；官网 mission：&quot;以 <strong>Enterprise World Model</strong> 让企业自主运营&quot;</td><td>官网 ✅ / 创立信息待一手确认</td></tr><tr><td>Bengio 与 Sutton 任 Maluuba 学术顾问</td><td>⚠️ <strong>未核实</strong>（维基条目未载；两人身份本身属实：Bengio 2018 图灵奖、Sutton 2024 图灵奖）</td><td>—</td></tr></tbody></table><hr><h2 id="六、传播链定位" tabindex="-1">六、传播链定位 <a class="header-anchor" href="#六、传播链定位" aria-label="Permalink to &quot;六、传播链定位&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skyfall 官方博客（2026-10-19，一手）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>OrcaRouter《SKY-001：Skyfall 的工程世界模型 vs GPT-6 Astra》（2026-10-20 01:49 GMT）</span></span>
<span class="line"><span>   ↓  ★ 转来文字的结构与「对比项/成本效率/设计速度/设计精度」表格形态吻合此题</span></span>
<span class="line"><span>VR陀螺（2026-10-20）· 搜狐（2026-10-21，含创始人叙事&quot;卖身微软15年后…&quot;）</span></span></code></pre></div><p>★ <strong>OrcaRouter 是 LLM 路由网关（api.orcarouter.ai）的内容页，不是技术媒体</strong>；同一天它还发布了多篇模板化 &quot;X vs GPT-6 Astra&quot; 对比文（另见 Mercury 3 等）→ 属<strong>模板化 SEO 产线</strong>，不是独立评测。<strong>转来那段是这条链的二手/三手转述，不是 Skyfall 的官方口径。</strong></p><hr><h2 id="七、跨主题关联" tabindex="-1">七、跨主题关联 <a class="header-anchor" href="#七、跨主题关联" aria-label="Permalink to &quot;七、跨主题关联&quot;">​</a></h2><ul><li><strong><code>weekly-416</code>（AI 取消的是前提，不是人）</strong>：SKY-001 是同一逻辑往<strong>空间设计</strong>推进 —— 它取消的不是工程师，而是&quot;<strong>人类逐步建模</strong>&quot;这个默认前提。</li><li><strong><code>gear-shaft-org-reinvention</code>（天轴困局）</strong>：若把 SKY-001 当&quot;外挂 CAD 插件&quot;用，同样落入天轴困局；它的价值恰在<strong>重排设计工序</strong>（先定层级 → 子节点并行展开）。官方那句&quot;层级让串行步数只与设计<strong>深度</strong>相关、与零件<strong>数量</strong>脱钩&quot;，本质是<strong>组织方式</strong>的变革而非速度的变革。</li><li><strong><code>openai-ai-native-organization</code>（执行变廉价 → 判断力变贵）</strong>：SKY-001 把&quot;建模执行&quot;打到 $0.005/例，稀缺品随之转移到<strong>层级怎么划分、约束怎么定义</strong> —— 谁定义总成树，谁掌握设计。</li><li><strong><code>liouville-goldbach-astra-claim</code>（声明审计）</strong>：<strong>GPT-6 Astra 第 2 次出现在&quot;被宣称碾压/攻克&quot;的位置</strong>（前次为 2026-09-21 的哥德巴赫声明审计）—— Astra 已成为<strong>对比表中的标准陪练</strong>，见到它就该查发布日与口径。</li><li><strong><code>dream-rsi</code> / <code>brain-self-evolution</code>（保底机制）</strong>：本库 <code>replay_eval</code> 的铁律是&quot;候选集含现状 + 严格更高才替换&quot;，正是为了抵御 0.6 个百分点级别的噪声差异；Skyfall 的自建自评基准没有这层保底。</li><li><strong>金风 / 风电</strong>：官方 FAQ <strong>明确把 &quot;energy and power systems&quot; 列为 SKY-001 的未来设计域</strong> → 与风机/风场设计直接相关（见 <code>topics/wind-energy/</code>）。</li></ul><hr><h2 id="八、判断-打折后的结论" tabindex="-1">八、判断（打折后的结论） <a class="header-anchor" href="#八、判断-打折后的结论" aria-label="Permalink to &quot;八、判断（打折后的结论）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>结论</th></tr></thead><tbody><tr><td>速度 / 成本</td><td><strong>确实有量级优势</strong>（约 50× 加速、约 1/150 成本），但这只对<strong>单例视觉设计生成</strong>成立</td></tr><tr><td>精度</td><td><strong>持平</strong>（+0.6 pt IoU），&quot;更高&quot;是包装；BIM 绝对精度仅 43.6%</td></tr><tr><td>可用性</td><td><strong>未证实</strong> —— waitlist、自承草图与几何可能对不上、无公开 API</td></tr><tr><td>评测独立性</td><td><strong>弱</strong> —— 自建基准 + 自评 + LLM 评委，无第三方复现</td></tr><tr><td>关注价值</td><td>不在 150×/50×，而在**「层级化拆解 + 并行展开」把长序列变成短步骤**这个思路</td></tr></tbody></table><p><strong>对金风的现实意义</strong>：官方把能源与电力系统列入未来设计域，方向上有相关性；但现阶段输出是&quot;视觉设计 + 构建序列&quot;，官方自己说下一步才做&quot;可编辑特征历史&quot;，<strong>不能直接产出可制造文件</strong>。若要试，先问三个问题：</p><ol><li>能否吃下风机层级（叶片 / 轮毂 / 机舱 / 塔架 → 零件）？</li><li>约束从哪来（载荷谱、IEC 标准、工艺公差）—— 官方管线里没提标准约束的注入点？</li><li>输出能否回到真实 CAD 特征树（而非只有网格 + 示意图）？</li></ol><hr><h2 id="九、取证边界-诚实交代" tabindex="-1">九、取证边界（诚实交代） <a class="header-anchor" href="#九、取证边界-诚实交代" aria-label="Permalink to &quot;九、取证边界（诚实交代）&quot;">​</a></h2><ul><li>✅ 官方博客<strong>全文</strong>已取（24.5 KB）→ <code>/tmp/sky001_blog.txt</code>；官网首页/FAQ 已取</li><li>⚠️ <code>skyfall.ai</code> 是 JS 壳（raw 3.5 KB / 正文 0），<strong>直取失败</strong>，经 <code>r.jina.ai</code> 文本代理取全文（与 openai.com 403 同类场景）</li><li>⚠️ 中文搜狐文章只取到 Sogou 的<strong>长摘要</strong>，正文未全取</li><li>❌ 未取到：Skyfall 团队其他成员、融资与投资方、&quot;2025-04 旧金山创立&quot;的一手确认、&quot;1.6 亿美元&quot;的一手确认</li><li>📌 本条目所用数字<strong>全部出自官方一手页面</strong>；凡属中文报道口径者已逐条标注</li></ul><hr><blockquote><p>方法论归属：本次属<strong>五类失真</strong>中的 <strong>② 程度夸大</strong>（&quot;全面碾压&quot;）+ <strong>③ 主体/口径错位</strong>（&quot;降低 150 倍&quot;），外加<strong>选择性省略</strong>（waitlist / 自承硬伤 / 基线不全）。清单见 <code>topics/science-news/index.md</code>。</p></blockquote>`,48)])])}const c=o(n,[["render",e]]);export{q as __pageData,c as default};
